def validate_dna(state: DNAState):
    dna = (
        state["dna_raw"]
        .upper()
        .replace(" ", "")
        .replace("\n", "")
    )

    invalid_characters = set(dna) - set("ATCG")

    if invalid_characters:
        return {
            "dna": dna,
            "is_valid": False,
            "error": (
                "A sequência contém caracteres inválidos: "
                f"{invalid_characters}"
            )
        }

    return {
        "dna": dna,
        "is_valid": True
    }

def analyze_dna(state: DNAState):
    dna = state["dna"]

    counts = Counter(dna)

    gc_content = (
        (counts["G"] + counts["C"]) / len(dna)
    ) * 100

    translation = str.maketrans(
        "ATCG",
        "TAGC"
    )

    complement = dna.translate(translation)

    codons = [
        dna[i:i + 3]
        for i in range(0, len(dna), 3)
        if len(dna[i:i + 3]) == 3
    ]

    return {
        "counts": dict(counts),
        "gc_content": round(gc_content, 2),
        "complement": complement,
        "codons": codons
    }

def build_prompt(state: DNAState):

    prompt = f"""
Você é um professor de genética e computação.

Explique os dados abaixo para uma pessoa
que nunca estudou genética.

DNA:
{state["dna"]}

Quantidade das bases:
{state["counts"]}

GC Content:
{state["gc_content"]}%

Sequência complementar:
{state["complement"]}

Códons:
{state["codons"]}

Use analogias simples.

Explique:
1. o que representam A, T, C e G;
2. o que significa sequência complementar;
3. o que é GC Content;
4. por que podemos dividir a sequência em códons.

Não faça diagnóstico médico e não atribua
significado clínico à sequência apenas com
essas informações.
"""

    return {
        "prompt": prompt
    }

def explain_with_ai(state: DNAState):

    response = llm.invoke(
        state["prompt"]
    )

    return {
        "explanation": response.content
    }

def invalid_sequence(state: DNAState):

    return {
        "explanation": (
            "Não consegui analisar a sequência. "
            + state["error"]
        )
    }

def route_validation(state: DNAState):

    if state["is_valid"]:
        return "valid"

    return "invalid"
